"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["95908"],{60936(e){e.exports=JSON.parse('{"id":"V4-114","slug":"perpetual-bond","term":"Perpetual Bond","also_known_as":[],"difficulty":"Intermediate","definition":"A perpetual bond is a bond with no maturity date, which pays interest indefinitely and whose principal does not have to be repaid, although the issuer may have the right to redeem it.","explanation":["Most bonds repay their face value on a set date. A perpetual bond, also called a perpetual or a consol, continues paying interest for as long as it exists.","Its value can be estimated as a perpetuity: the annual interest divided by the required yield. For example, a perpetual bond paying 50 a year, when investors require a 6% yield, would be worth about 833.","Perpetual bonds are commonly issued by banks and insurers, often as a form of capital that can absorb losses, such as Additional Tier 1 bonds. These usually include call options allowing the issuer to redeem them after a set period, and may allow interest payments to be cancelled or the bonds to be written down in a crisis.","Perpetual bonds are very sensitive to interest rate changes, because their cash flows extend indefinitely. They also carry the issuer\u2019s credit risk. In 2023, the write-down of Credit Suisse\u2019s Additional Tier 1 bonds to zero, as part of its rescue, showed the risks of loss-absorbing perpetual bonds."],"note":"","total":1725,"prev":{"slug":"permanent-difference","term":"Permanent Difference"},"next":{"slug":"perpetual-growth-method","term":"Perpetual Growth Method"}}')}}]);